'use strict';

// MODULES //

var path = require( 'node:path' );
var readFile = require( 'node:fs/promises' ).readFile;
var equal = require( '@data-apis/canonical/equal' );
var sha256 = require( '@data-apis/canonical/sha256' );
var walkFiles = require( '@data-apis/files/walk-files' );
var loadRegistry = require( '@data-apis/registry/load' );
var getSource = require( '@data-apis/registry/get-source' );
var sourceFingerprint = require( '@data-apis/registry/source-fingerprint' );
var assertSchema = require( '@data-apis/schema/assert' );
var assertCanonicalGzip = require( '@data-apis/record/assert-canonical-gzip' );
var parseGzipEnvelope = require( '@data-apis/record/parse-gzip-envelope' );
var serializeIndex = require( '@data-apis/record/serialize-index' );
var validateEnvelope = require( '@data-apis/record/validate-envelope' );
var validateIndexRow = require( '@data-apis/record/validate-index-row' );
var indexKey = require( '@data-apis/record/index-key' );
var validateRepository = require( '@data-apis/repository/validate' );


// FUNCTIONS //

/**
* Parses a JSON file with contextual diagnostics.
*
* @private
* @param {string} filePath - file path
* @returns {Promise<Object>} parsed value
*/
async function readJson( filePath ) {
	try {
		return JSON.parse( await readFile( filePath, 'utf8' ) );
	} catch ( error ) {
		throw new Error( 'Unable to parse ' + filePath + ': ' + error.message, {
			'cause': error
		} );
	}
}

/**
* Validates manifest structure and deterministic ordering.
*
* @private
* @param {Object} manifest - manifest
*/
function validateManifest( manifest ) {
	var seen = new Set();
	var previous = '';

	if ( !manifest || manifest.schema !== 'harvest-manifest-v1' || typeof manifest.base_sha !== 'string' || !Array.isArray( manifest.files ) ) {
		throw new Error( 'Invalid harvest manifest' );
	}
	manifest.files.forEach( function validateFile( file ) {
		if ( !file || typeof file.path !== 'string' || !Number.isSafeInteger( file.size ) || file.size < 0 || !/^[0-9a-f]{64}$/.test( file.sha256 ) ) {
			throw new Error( 'Invalid harvest manifest file entry' );
		}
		if ( file.path !== 'data/index.json' && !/^data\/[a-z0-9-]+\/[a-z0-9-]+\/\d{4}_\d{2}_\d{2}T\d{2}_\d{2}_\d{2}Z__sha256_[0-9a-f]{64}\.json\.gz$/.test( file.path ) ) {
			throw new Error( 'Manifest path is outside the publication whitelist: ' + file.path );
		}
		if ( seen.has( file.path ) ) {
			throw new Error( 'Duplicate manifest path: ' + file.path );
		}
		if ( previous && previous > file.path ) {
			throw new Error( 'Manifest files are not sorted' );
		}
		seen.add( file.path );
		previous = file.path;
	} );
}

/**
* Validates summary structure needed by publication.
*
* @private
* @param {Object} summary - summary
* @param {Object} manifest - manifest
*/
function validateSummary( summary, manifest ) {
	var records;

	if ( !summary || summary.schema !== 'harvest-summary-v1' || typeof summary.has_source_errors !== 'boolean' || !Array.isArray( summary.new_records ) || !Array.isArray( summary.sources ) || !Array.isArray( summary.warnings ) ) {
		throw new Error( 'Invalid harvest summary' );
	}
	if ( summary.base_sha !== manifest.base_sha ) {
		throw new Error( 'Summary and manifest base revisions differ' );
	}
	if ( !equal( summary.new_records, summary.new_records.slice().sort() ) ) {
		throw new Error( 'Summary record paths are not sorted' );
	}
	records = manifest.files.filter( function isRecord( file ) {
		return file.path.endsWith( '.json.gz' );
	} ).map( function toPath( file ) {
		return file.path;
	} );
	if ( !equal( records, summary.new_records ) ) {
		throw new Error( 'Summary record paths do not match manifest record paths' );
	}
}

/**
* Validates origin identity against the registered source.
*
* @private
* @param {Object} origin - stored origin
* @param {Object} source - registered source
*/
function validateOrigin( origin, source ) {
	if ( source.type !== origin.type ) {
		throw new Error( 'Stored origin type differs from registered source' );
	}
	if ( source.type === 'ci_artifact' ) {
		if ( source.provider !== origin.provider || source.project.toLowerCase() !== origin.project.locator.toLowerCase() ) {
			throw new Error( 'Stored CI origin differs from registered source' );
		}
	} else if ( source.url !== origin.endpoint ) {
		throw new Error( 'Stored URL origin differs from registered source' );
	}
}


// MAIN //

/**
* Validates a harvest output bundle against the checked-in repository.
*
* @param {Object} options - validation options
* @param {string} options.rootDirectory - repository root
* @param {string} options.outputDirectory - output directory
* @returns {Promise<Object>} validated manifest and summary
*/
async function validateOutput( options ) {
	var registryPath = options.registryPath || path.join( options.rootDirectory, 'registry/data.json' );
	var dataDirectory = options.dataDirectory || path.join( options.rootDirectory, 'data' );
	var registry = await loadRegistry( registryPath );
	var repository = await validateRepository( {
		'dataDirectory': dataDirectory,
		'registry': registry,
		'all': false
	} );
	var manifest = await readJson( path.join( options.outputDirectory, 'manifest.json' ) );
	var summary = await readJson( path.join( options.outputDirectory, 'summary.json' ) );
	var actualFiles = await walkFiles( options.outputDirectory );
	var expectedFiles;
	var newRecordFiles;
	var existingPaths = new Set( repository.paths );
	var outputIndex;
	var rowByPath;
	var rowKeys;
	var validateOptions;
	var relative;
	var envelope;
	var lookup;
	var bytes;
	var file;

	validateManifest( manifest );
	validateSummary( summary, manifest );
	expectedFiles = ['manifest.json', 'summary.json'].concat( manifest.files.map( function toPath( file ) {
		return file.path;
	} ) ).sort();
	if ( !equal( actualFiles, expectedFiles ) ) {
		throw new Error( 'Output directory contains files outside the manifest' );
	}
	for ( file of manifest.files ) {
		bytes = await readFile( path.join( options.outputDirectory, ...file.path.split( '/' ) ) );

		if ( bytes.length !== file.size || sha256( bytes ) !== file.sha256 ) {
			throw new Error( 'Manifest size or hash mismatch: ' + file.path );
		}
	}
	newRecordFiles = manifest.files.filter( function isRecord( file ) {
		return file.path.endsWith( '.json.gz' );
	} );
	if ( newRecordFiles.length === 0 ) {
		if ( manifest.files.length !== 0 ) {
			throw new Error( 'No-change output must not contain data files' );
		}
		return {
			'manifest': manifest,
			'summary': summary
		};
	}
	if ( !manifest.files.some( function isIndex( file ) { return file.path === 'data/index.json'; } ) ) {
		throw new Error( 'Changed harvest output is missing data/index.json' );
	}
	outputIndex = await readJson( path.join( options.outputDirectory, 'data/index.json' ) );
	assertSchema( 'data-index-v1', outputIndex );
	if ( ( await readFile( path.join( options.outputDirectory, 'data/index.json' ), 'utf8' ) ) !== serializeIndex( outputIndex.records ) ) {
		throw new Error( 'Output data index is not deterministic' );
	}
	rowByPath = new Map( outputIndex.records.map( function mapRow( row ) {
		return [row.path, row];
	} ) );
	if ( rowByPath.size !== outputIndex.records.length ) {
		throw new Error( 'Output index contains duplicate record paths' );
	}
	rowKeys = new Set( outputIndex.records.map( indexKey ) );
	if ( rowKeys.size !== outputIndex.records.length ) {
		throw new Error( 'Output index contains duplicate record keys' );
	}
	repository.index.records.forEach( function validateExisting( row ) {
		if ( !equal( rowByPath.get( row.path ), row ) ) {
			throw new Error( 'Output index changed an existing row: ' + row.path );
		}
	} );
	for ( file of newRecordFiles ) {
		relative = file.path.slice( 'data/'.length );

		if ( existingPaths.has( relative ) ) {
			throw new Error( 'Harvest output attempts to overwrite an existing record: ' + relative );
		}
		lookup = getSource( registry, relative.split( '/' )[ 0 ], relative.split( '/' )[ 1 ] );
		if ( !lookup.library || !lookup.source ) {
			throw new Error( 'Harvest output references an unregistered source: ' + relative );
		}
		bytes = await readFile( path.join( options.outputDirectory, ...file.path.split( '/' ) ) );
		envelope = parseGzipEnvelope( bytes );
		if ( envelope.harvest.source_fingerprint !== sourceFingerprint( lookup.source ) ) {
			throw new Error( 'Stored source fingerprint differs from registry: ' + relative );
		}
		validateOrigin( envelope.harvest.origin, lookup.source );
		validateOptions = {
			'expectedName': lookup.library.report_name || lookup.library.id
		};
		validateEnvelope( envelope, relative, validateOptions );
		validateIndexRow( rowByPath.get( relative ), envelope, relative, validateOptions );
		assertCanonicalGzip( bytes, envelope );
		existingPaths.add( relative );
	}
	if ( rowByPath.size !== existingPaths.size || Array.from( existingPaths ).some( function missing( recordPath ) {
		return !rowByPath.has( recordPath );
	} ) ) {
		throw new Error( 'Output index does not cover exactly the existing and new records' );
	}
	return {
		'manifest': manifest,
		'summary': summary,
		'index': outputIndex
	};
}


// EXPORTS //

module.exports = validateOutput;
